function macNorm(s){ return String(s).toUpperCase().replace(/[^0-9A-F]/g,''); }
function macValid(s){ return /^([0-9A-Fa-f]{2}[:-]){5}[0-9A-Fa-f]{2}$/.test(String(s).trim()); }
function macFormat(s, sep){
  sep=sep||':';
  var h=macNorm(s);
  if(h.length!==12) return { error:'MAC 应为 12 个十六进制字符' };
  var out=[];
  for(var i=0;i<12;i+=2) out.push(h.slice(i,i+2));
  return { error:null, mac:out.join(sep) };
}
function macRandom(sep, rnd){
  sep=sep||':';
  var hex='0123456789ABCDEF', s='';
  for(var i=0;i<6;i++){ var b=Math.floor(rnd()*256); s+=hex[(b>>4)&15]+hex[b&15]; }
  return s.match(/.{2}/g).join(sep);
}
function macIsMulticast(s){ var h=macNorm(s); if(h.length!==12) return false; return (parseInt(h[1],16)&1)===1; }
function macIsLocal(s){ var h=macNorm(s); if(h.length!==12) return false; return (parseInt(h[1],16)&2)===2; }
var MAC_OUI={ '001B44':'Juniper', 'FCFBFB':'Cisco', '001A2B':'Google', '001634':'Apple', 'D850E6':'Amazon', '001D0F':'Dell' };
function macOui(s){ var h=macNorm(s); if(h.length!==12) return { error:'invalid' }; var oui=h.slice(0,6); return { oui:oui, vendor: MAC_OUI[oui]||'未知厂商' }; }
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { macValid:macValid, macFormat:macFormat, macRandom:macRandom, macIsMulticast:macIsMulticast, macIsLocal:macIsLocal, macOui:macOui };
}
if (typeof window !== 'undefined') {
  window.MacForgePure = { macValid:macValid, macFormat:macFormat, macRandom:macRandom, macIsMulticast:macIsMulticast, macIsLocal:macIsLocal, macOui:macOui };
}
